import{_ as e,o as a,c as r,a2 as d}from"./chunks/framework.F7eQ-ohH.js";const n="/bzygq/assets/c65c26c09c554c7da146fcdabbe5edb2.H38b74YP.png",b=JSON.parse('{"title":"Transformer与推理参数","description":"","frontmatter":{},"headers":[],"relativePath":"AI应用开发/二、LLM教程/Transformer与推理参数.md","filePath":"AI应用开发/二、LLM教程/Transformer与推理参数.md","lastUpdated":1788883925000}'),s={name:"AI应用开发/二、LLM教程/Transformer与推理参数.md"};function o(p,t,i,l,h,c){return a(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="transformer与推理参数" tabindex="-1">Transformer与推理参数 <a class="header-anchor" href="#transformer与推理参数" aria-label="Permalink to &quot;Transformer与推理参数&quot;">​</a></h1><p>央国企技术面试一般不会要求你手推 Transformer 公式，但至少要知道它为什么适合大模型，以及常见推理参数会怎样影响输出。</p><p>这一篇重点解决两个问题：第一，Transformer 需要理解到什么程度；第二，temperature、top_p、max_tokens 这些参数在工程里怎么用。</p><h2 id="一、transformer-要理解到什么程度" tabindex="-1">一、Transformer 要理解到什么程度 <a class="header-anchor" href="#一、transformer-要理解到什么程度" aria-label="Permalink to &quot;一、Transformer 要理解到什么程度&quot;">​</a></h2><p><img src="'+n+`" alt=""></p><p>Transformer 的核心是注意力机制。注意力机制可以让模型在处理一个 Token 时，同时关注上下文中的其他 Token，从而理解词与词之间的关系。比如“请把这份合同里的付款条款提取出来”，模型在理解“付款条款”时，需要联系“合同”“提取”“条款”等多个上下文信息。</p><p>传统 RNN 更强调顺序处理，前一个状态影响后一个状态。Transformer 则可以并行处理序列，并通过注意力计算不同位置之间的关系，所以更适合大规模训练。</p><h2 id="二、几个关键词" tabindex="-1">二、几个关键词 <a class="header-anchor" href="#二、几个关键词" aria-label="Permalink to &quot;二、几个关键词&quot;">​</a></h2><p>可以按这几个关键词准备：</p><table tabindex="0"><thead><tr><th>关键词</th><th>面试解释</th></tr></thead><tbody><tr><td>Attention</td><td>计算不同 Token 之间的相关程度</td></tr><tr><td>Self-Attention</td><td>同一段文本内部 Token 互相建立关系</td></tr><tr><td>Multi-Head Attention</td><td>从多个角度捕捉语义、语法和上下文关系</td></tr><tr><td>Position Encoding</td><td>给模型补充位置信息，否则模型不知道 Token 顺序</td></tr><tr><td>Feed Forward</td><td>对注意力结果做进一步非线性变换</td></tr><tr><td>Masked Attention</td><td>生成式模型只能看当前位置之前的内容，保证逐步生成</td></tr></tbody></table><p>面试里可以这样回答：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Transformer 的价值在于用注意力机制建模上下文关系。</span></span>
<span class="line"><span>它不像 RNN 那样必须严格按顺序处理，所以训练效率更高，也更容易扩展到大规模参数和数据。</span></span>
<span class="line"><span>对大语言模型来说，Transformer 让模型可以在较长上下文中捕捉词语、句子和段落之间的依赖关系。</span></span></code></pre></div><p>这个答案不花哨，但足够稳。</p><h2 id="三、推理参数如何影响输出" tabindex="-1">三、推理参数如何影响输出 <a class="header-anchor" href="#三、推理参数如何影响输出" aria-label="Permalink to &quot;三、推理参数如何影响输出&quot;">​</a></h2><p>调用模型接口时，经常会看到 temperature、top_p、max_tokens、stop 等参数。它们不只是配置项，而是会直接影响输出稳定性和成本。</p><table tabindex="0"><thead><tr><th>参数</th><th>含义</th><th>工程影响</th></tr></thead><tbody><tr><td>temperature</td><td>控制随机性</td><td>越低越稳定，越高越发散</td></tr><tr><td>top_p</td><td>从累计概率范围内采样</td><td>控制候选 Token 范围</td></tr><tr><td>max_tokens</td><td>限制最大输出长度</td><td>控制成本和响应时间</td></tr><tr><td>stop</td><td>遇到指定标记停止生成</td><td>用于结构化输出或多段任务</td></tr><tr><td>presence_penalty</td><td>降低重复提及同一主题的概率</td><td>适合创作类任务</td></tr><tr><td>frequency_penalty</td><td>降低重复词句概率</td><td>减少重复输出</td></tr></tbody></table><p>在企业系统中，很多场景更适合低随机性。比如制度问答、合同条款提取、工单分类、审批意见生成，通常希望答案稳定、可复现、少发挥。这类任务可以把 temperature 设置得低一些。</p><p>创意写作、营销文案、头脑风暴这类任务，可以适当提高随机性。</p><h2 id="四、不同任务的参数倾向" tabindex="-1">四、不同任务的参数倾向 <a class="header-anchor" href="#四、不同任务的参数倾向" aria-label="Permalink to &quot;四、不同任务的参数倾向&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>参数倾向</th></tr></thead><tbody><tr><td>制度问答</td><td>低 temperature，限制输出长度，要求引用来源</td></tr><tr><td>合同条款抽取</td><td>低 temperature，结构化输出，失败重试</td></tr><tr><td>工单分类</td><td>低 temperature，固定枚举标签</td></tr><tr><td>会议纪要总结</td><td>中低 temperature，保留要点和行动项</td></tr><tr><td>公众号标题生成</td><td>中高 temperature，多候选输出</td></tr><tr><td>方案头脑风暴</td><td>中高 temperature，鼓励发散</td></tr></tbody></table><p>面试表达可以这样说：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我会根据任务类型调整推理参数。</span></span>
<span class="line"><span>如果是知识库问答、分类、抽取等严肃场景，会降低 temperature，限制输出长度，并要求结构化输出。</span></span>
<span class="line"><span>如果是文案生成或方案发散，可以适当提高随机性。</span></span></code></pre></div><h2 id="五、面试常问问题" tabindex="-1">五、面试常问问题 <a class="header-anchor" href="#五、面试常问问题" aria-label="Permalink to &quot;五、面试常问问题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>问题</th><th>回答重点</th></tr></thead><tbody><tr><td>Transformer 为什么适合大模型？</td><td>注意力机制、并行计算、可扩展</td></tr><tr><td>Attention 是什么？</td><td>让模型判断当前 Token 应该关注哪些上下文</td></tr><tr><td>temperature 越高越好吗？</td><td>不一定，严肃任务通常要低随机性</td></tr><tr><td>max_tokens 有什么用？</td><td>控制输出长度、成本和响应时间</td></tr><tr><td>为什么同一个问题回答不一样？</td><td>采样参数、上下文变化、模型随机性</td></tr></tbody></table>`,24)])])}const u=e(s,[["render",o]]);export{b as __pageData,u as default};
